namespace Payments;

public sealed class PaymentGateway
{
    private readonly Dictionary<string, (string CardToken, decimal Amount)> _charges = new();

    public Task<ChargeResult> ChargeAsync(string cardToken, decimal amount)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(cardToken);

        if (amount <= 0)
            throw new ArgumentOutOfRangeException(nameof(amount), "Amount must be positive.");

        if (amount > 999_999.99m)
            throw new ArgumentOutOfRangeException(nameof(amount), "Amount exceeds maximum.");

        var chargeId = $"ch_{Guid.NewGuid():N}";
        _charges[chargeId] = (cardToken, amount);
        return Task.FromResult(new ChargeResult(chargeId, Success: true));
    }

    public Task<RefundResult> RefundAsync(string chargeId)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(chargeId);

        if (!_charges.Remove(chargeId))
            return Task.FromResult(new RefundResult(RefundId: string.Empty, Success: false));

        var refundId = $"rf_{Guid.NewGuid():N}";
        return Task.FromResult(new RefundResult(refundId, Success: true));
    }

    public Task<WebhookResult> ProcessWebhookAsync(string eventType, string payload)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(eventType);
        ArgumentException.ThrowIfNullOrWhiteSpace(payload);

        var handled = eventType switch
        {
            "charge.succeeded" or "charge.failed" or "refund.created" => true,
            _ => false,
        };

        return Task.FromResult(new WebhookResult(eventType, Handled: handled));
    }
}

public record ChargeResult(string ChargeId, bool Success);
public record RefundResult(string RefundId, bool Success);
public record WebhookResult(string EventType, bool Handled);

