using Payments;

namespace Payments.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private PaymentGateway _gateway = null!;

    [TestInitialize]
    public void Setup() => _gateway = new PaymentGateway();

    // ── ChargeAsync ─────────────────────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ValidInput_ReturnsSuccessWithChargeId()
    {
        var result = await _gateway.ChargeAsync("tok_visa", 50.00m);

        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.ChargeId);
        Assert.StartsWith("ch_", result.ChargeId);
    }

    [TestMethod]
    [DataRow(0.01)]
    [DataRow(1.00)]
    [DataRow(999_999.99)]
    public async Task ChargeAsync_BoundaryAmounts_Succeeds(double amount)
    {
        var result = await _gateway.ChargeAsync("tok_visa", (decimal)amount);

        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    [DataRow(0.0)]
    [DataRow(-1.0)]
    [DataRow(-100.0)]
    public async Task ChargeAsync_NonPositiveAmount_ThrowsArgumentOutOfRange(double amount)
    {
        await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_visa", (decimal)amount));
    }

    [TestMethod]
    public async Task ChargeAsync_ExceedsMaximumAmount_ThrowsArgumentOutOfRange()
    {
        await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_visa", 1_000_000.00m));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public async Task ChargeAsync_InvalidCardToken_ThrowsArgumentException(string? token)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(token!, 10m));
    }

    [TestMethod]
    public async Task ChargeAsync_MultipleCharges_ReturnUniqueIds()
    {
        var r1 = await _gateway.ChargeAsync("tok_visa", 10m);
        var r2 = await _gateway.ChargeAsync("tok_visa", 20m);

        Assert.AreNotEqual(r1.ChargeId, r2.ChargeId);
    }

    // ── RefundAsync ─────────────────────────────────────────────

    [TestMethod]
    public async Task RefundAsync_ExistingCharge_ReturnsSuccessWithRefundId()
    {
        var charge = await _gateway.ChargeAsync("tok_visa", 75m);

        var refund = await _gateway.RefundAsync(charge.ChargeId);

        Assert.IsTrue(refund.Success);
        Assert.IsNotNull(refund.RefundId);
        Assert.StartsWith("rf_", refund.RefundId);
    }

    [TestMethod]
    public async Task RefundAsync_NonExistentChargeId_ReturnsFailure()
    {
        var refund = await _gateway.RefundAsync("ch_doesnotexist");

        Assert.IsFalse(refund.Success);
        Assert.AreEqual(string.Empty, refund.RefundId);
    }

    [TestMethod]
    public async Task RefundAsync_SameChargeTwice_SecondRefundFails()
    {
        var charge = await _gateway.ChargeAsync("tok_visa", 100m);

        var first = await _gateway.RefundAsync(charge.ChargeId);
        var second = await _gateway.RefundAsync(charge.ChargeId);

        Assert.IsTrue(first.Success);
        Assert.IsFalse(second.Success);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public async Task RefundAsync_InvalidChargeId_ThrowsArgumentException(string? chargeId)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(chargeId!));
    }

    // ── ProcessWebhookAsync ─────────────────────────────────────

    [TestMethod]
    [DataRow("charge.succeeded")]
    [DataRow("charge.failed")]
    [DataRow("refund.created")]
    public async Task ProcessWebhookAsync_KnownEventType_ReturnsHandled(string eventType)
    {
        var result = await _gateway.ProcessWebhookAsync(eventType, "{\"id\":\"evt_1\"}");

        Assert.IsTrue(result.Handled);
        Assert.AreEqual(eventType, result.EventType);
    }

    [TestMethod]
    [DataRow("unknown.event")]
    [DataRow("customer.created")]
    public async Task ProcessWebhookAsync_UnknownEventType_ReturnsNotHandled(string eventType)
    {
        var result = await _gateway.ProcessWebhookAsync(eventType, "{\"id\":\"evt_1\"}");

        Assert.IsFalse(result.Handled);
    }

    [TestMethod]
    [DataRow(null, "payload")]
    [DataRow("", "payload")]
    [DataRow("charge.succeeded", null)]
    [DataRow("charge.succeeded", "")]
    public async Task ProcessWebhookAsync_InvalidInputs_ThrowsArgumentException(
        string? eventType, string? payload)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ProcessWebhookAsync(eventType!, payload!));
    }

    // ── End-to-end: Charge then Refund ──────────────────────────

    [TestMethod]
    public async Task ChargeAndRefund_FullFlow_Succeeds()
    {
        var charge = await _gateway.ChargeAsync("tok_mastercard", 250m);
        Assert.IsTrue(charge.Success);

        var refund = await _gateway.RefundAsync(charge.ChargeId);
        Assert.IsTrue(refund.Success);
        Assert.StartsWith("rf_", refund.RefundId);
    }
}

using Payments;

namespace Payments.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private PaymentGateway _gateway = null!;

    [TestInitialize]
    public void Setup() => _gateway = new PaymentGateway();

    // ── ChargeAsync ─────────────────────────────────────────────

    [TestMethod]
